import {validateTemplate} from './branding.js?v=receipt-checked-81';
import {projectStages} from './production.js?v=booking-15';
export const services=['Cinematic','Candid','Traditional Photo','Traditional Video','Drone'];
export const leadSources=['Reference','Instagram','Facebook','Others'];
export const budgets=['Agreed','Negotiation','Low'];
export const bookingStatuses=['Quote Sent','Booked','Negotiation','Tentative','Canceled','Lost'];
export const expenseCategories=['Camera Rent','Lens Rent','Drone Rent','Travelling','Fuel','Hotel','Food','Team Payment','Editing','Printing','Album','Courier','Other Expenses'];
export const deliveryItems=['Bride Album','Groom Album','Teaser','Highlight','Groom TV','Bride TV','Reels','Raw Data'];
export const paymentStages=['Booking','On-event','Before Event','After Event','Final Payment','Custom','Album printing','Delivery','Other'];
export const serviceList=value=>Array.isArray(value)?value:String(value||'').split(',').map(s=>s.trim()).filter(Boolean);
export const finalQuote=(price,discount=0)=>{price=Number(price);discount=Number(discount);if(!Number.isFinite(price)||!Number.isFinite(discount)||price<0||discount<0||discount>price)throw Error('Discount must be between zero and package price');return price-discount;};
export const validDate=value=>{if(!/^\d{4}-\d{2}-\d{2}$/.test(value||''))return false;const d=new Date(value+'T12:00:00Z');return !Number.isNaN(+d)&&d.toISOString().slice(0,10)===value;};
export function validateData(d){
 const tables=['clients','enquiries','events','payments','projects','tasks','expenses','team','documents'];
 if(!d||d.version!==1||!d.settings||typeof d.settings.company!=='string'||!Number.isInteger(d.nextClient)||d.nextClient<1)throw Error('Unsupported backup format');
 for(const table of tables){if(!Array.isArray(d[table]))throw Error('Missing '+table);const ids=new Set();for(const row of d[table]){if(!row||typeof row.id!=='string'||!row.id||ids.has(row.id))throw Error('Missing or duplicate ID in '+table);ids.add(row.id);}}
 if(d.assignments!==undefined&&!Array.isArray(d.assignments))throw Error('Invalid assignments');
 const client=id=>d.clients.find(c=>c.id===id),event=id=>d.events.find(e=>e.id===id),team=id=>d.team.some(t=>t.id===id),number=n=>Number.isFinite(n)&&n>=0;
 for(const c of d.clients){if(typeof c.name!=='string'||!c.name.trim()||!number(c.amount))throw Error('Invalid client');if(c.price!==undefined)finalQuote(c.price,c.discount||0);if(c.financeMode&&!['Shared','Per day'].includes(c.financeMode))throw Error('Invalid finance structure');}
 for(const q of d.enquiries)if(typeof q.name!=='string'||!q.name.trim()||!number(q.amount)||q.client&&!client(q.client))throw Error('Invalid enquiry');for(const t of d.team)if(typeof t.name!=='string'||!t.name.trim())throw Error('Invalid team member');
 for(const e of d.events){if(!client(e.client)||typeof e.type!=='string'||typeof e.date!=='string'||e.date&&!validDate(e.date)||typeof e.venue!=='string'||!Array.isArray(e.team)||e.team.some(id=>!team(id)))throw Error('Invalid event links or details');if(!e.timeNotRecorded&&(!/^([01]\d|2[0-3]):[0-5]\d$/.test(e.start)||!/^([01]\d|2[0-3]):[0-5]\d$/.test(e.end)||e.start>=e.end))throw Error('Invalid event times');if(e.quotation!==undefined&&!number(e.quotation))throw Error('Invalid day quotation');}
 for(const p of d.payments){if(!client(p.client)||!number(p.amount)||p.amount<=0||(!validDate(p.date)&&!(p.sourceDateUnknown&&p.date===''))||p.event&&event(p.event)?.client!==p.client)throw Error('Invalid payment or client/event link');}
 for(const x of d.expenses){if(!number(x.amount)||(!validDate(x.date)&&!(x.sourceDateUnknown&&x.date===''))||typeof x.title!=='string'||x.client&&!client(x.client)||x.event&&event(x.event)?.client!==x.client)throw Error('Invalid expense or client/event link');}
 for(const p of d.projects)if(!event(p.event)||!Number.isInteger(p.stage)||p.stage<0||p.stage>=projectStages(p).length||p.owner&&!team(p.owner))throw Error('Invalid production project');
 for(const p of d.projects)if(p.stageNames&&(!Array.isArray(p.stageNames)||p.stageNames.length<2||p.stageNames.length>50||p.stageNames[0]!=='Shoot Completed'||p.stageNames.at(-1)!=='Completed'||p.stageNames.some(s=>typeof s!=='string'||!s.trim())||new Set(p.stageNames).size!==p.stageNames.length))throw Error('Invalid production stages');
 for(const p of d.projects)if(p.completedStages&&(!Array.isArray(p.completedStages)||new Set(p.completedStages).size!==p.completedStages.length||p.completedStages.some(s=>!projectStages(p).includes(s))))throw Error('Invalid completed project items');
 const assignmentIds=new Set();for(const a of d.assignments||[]){if(typeof a.id!=='string'||assignmentIds.has(a.id)||!event(a.event)||!team(a.member)||!number(a.charge)||!number(a.paid)||a.paid>a.charge)throw Error('Invalid team assignment');assignmentIds.add(a.id);}
 for(const t of d.tasks)if(typeof t.title!=='string'||!validDate(t.due)||t.client&&!client(t.client)||t.event&&!event(t.event)||t.project&&!d.projects.some(p=>p.id===t.project)||t.owner&&!team(t.owner))throw Error('Invalid task or linked record');
 for(const t of d.tasks){const p=t.project?d.projects.find(p=>p.id===t.project):null,e=t.event?event(t.event):p?event(p.event):null;if(p&&t.event&&p.event!==t.event||e&&t.client&&e.client!==t.client)throw Error('Task links refer to different clients or events');}
 for(const x of d.documents)if(!client(x.client)||typeof x.name!=='string'||typeof x.data!=='string'||!/^data:[^,]*;base64,/.test(x.data))throw Error('Invalid document');
 for(const c of d.clients){const es=d.events.filter(e=>e.client===c.id),quote=d.packages?.some(p=>p.client===c.id)?d.packages.filter(p=>p.client===c.id).reduce((n,p)=>n+finalQuote(p.price,p.discount),0):c.financeMode==='Per day'?es.reduce((n,e)=>n+Number(e.quotation||0),0):c.amount,paid=d.payments.filter(p=>p.client===c.id).reduce((n,p)=>n+p.amount,0);if(paid>quote)throw Error('Client payments exceed quotation');if(!d.packages?.some(p=>p.client===c.id)&&c.financeMode==='Per day')for(const e of es)if(d.payments.filter(p=>p.event===e.id).reduce((n,p)=>n+p.amount,0)>Number(e.quotation||0))throw Error('Event payments exceed day quotation');}
 if(d.packages){const ids=new Set(),eventLinks=new Set();for(const p of d.packages){if(!p.id||ids.has(p.id)||!client(p.client)||!Array.isArray(p.events)||p.events.some(id=>event(id)?.client!==p.client))throw Error('Invalid package links');ids.add(p.id);for(const id of p.events){if(eventLinks.has(id))throw Error('An event is linked to multiple packages');eventLinks.add(id);}if(p.delivery){if(!Array.isArray(p.delivery.items))throw Error('Invalid package delivery');const itemIds=new Set();for(const i of p.delivery.items){if(!i.id||itemIds.has(i.id)||!i.label?.trim()||!['deliverable','complimentary'].includes(i.kind)||!['Not set','No','In progress','Partial','Yes','Not required'].includes(i.status))throw Error('Invalid delivery item');if(i.quantity!==undefined&&i.quantity!==null&&(!Number.isInteger(i.quantity)||i.quantity<1)||i.deliveredQuantity!==undefined&&(!Number.isFinite(i.deliveredQuantity)||i.deliveredQuantity<0||i.quantity&&i.deliveredQuantity>i.quantity)||i.deliveredDate&&!validDate(i.deliveredDate))throw Error('Invalid delivery quantity or date');itemIds.add(i.id);}}finalQuote(p.price,p.discount);const paid=d.payments.filter(x=>x.package===p.id).reduce((n,x)=>n+x.amount,0);if(paid>finalQuote(p.price,p.discount))throw Error('Package receipts exceed quotation');}for(const p of d.payments)if(p.package&&!d.packages.some(x=>x.id===p.package&&x.client===p.client&&(!p.event||x.events.includes(p.event))))throw Error('Invalid payment package');}
 if(d.invoices){if(!Array.isArray(d.invoices))throw Error('Invalid invoices');const numbers=new Set();for(const i of d.invoices){if(!i.id||!/^([A-Za-z0-9_-]{0,16})\d{3,}$/.test(i.number)||numbers.has(i.number)||!client(i.client)||!(i.clientInvoice?true:i.documentKind?d.payments.some(p=>p.id===i.paymentId&&p.client===i.client)&&['receipt','stage-invoice'].includes(i.documentKind):d.packages?.some(p=>p.id===i.package&&p.client===i.client)))throw Error('Invalid invoice identity');if(i.companyId&&d.companyId&&i.companyId!==d.companyId)throw Error('Invoice belongs to another company');if(i.sequence!==undefined&&(!Number.isSafeInteger(i.sequence)||i.sequence<1))throw Error('Invalid invoice sequence');numbers.add(i.number);}}
 if(d.settings.invoiceTemplates){if(!Array.isArray(d.settings.invoiceTemplates))throw Error('Invalid templates');const ids=new Set();for(const t of d.settings.invoiceTemplates){if(!t.id||ids.has(t.id))throw Error('Invalid template identity');ids.add(t.id);validateTemplate(t);}}
 return d;
}
export function bookingState(e,c){const state=['Canceled','Lost'].includes(c?.status)?c.status:e.bookingStatus||c?.status;if(['Canceled','Lost'].includes(state))return state;return ['Booked','Confirmed','Completed'].includes(state)?'Confirmed':'Tentative';}


export function deliveryPlan(e){const d={...(e.delivery||{})};if(d.requirements?.trim()){const items=[...new Set(d.requirements.split('\n').map(x=>x.trim()).filter(Boolean))];return {data:d,items,labels:{}}}return {data:d,items:deliveryItems,labels:{}};}
